/**
 * Bundled supplier quotes. All fictional, generated by `pnpm samples`
 * (scripts/make-samples.ts), which also writes the ground truth used by evals.
 */
export interface SampleQuote {
  id: string;
  label: string;
  /** What makes this sample interesting for extraction. */
  note: string;
}

export const SAMPLE_QUOTES: readonly SampleQuote[] = [
  { id: "perfiles-quillen-table", label: "Perfiles Quillén, profiles", note: "Clean table layout" },
  { id: "vidrieria-tres-lomas-list", label: "Vidriería Tres Lomas, glass", note: "Bulleted list, fractional m²" },
  { id: "herrajes-calandria-typewriter", label: "Herrajes Calandria, hardware", note: "Monospaced typewriter layout" },
  { id: "importadora-lapacho-usd", label: "Importadora Lapacho, hardware", note: "Priced in US dollars" },
  { id: "perfiles-quillen-discount", label: "Perfiles Quillén, with discount", note: "Discount line" },
  { id: "templados-aguaribay-missing-sku", label: "Templados Aguaribay, glass", note: "One line has no SKU" },
  { id: "distribuidora-nandubay-compact", label: "Distribuidora Ñandubay, mixed", note: "Compact layout, unknown SKU" },
  { id: "metalurgica-coihue-no-number", label: "Metalúrgica Coihue, profiles", note: "No quote number, date in words" },
  { id: "vidrieria-tres-lomas-long", label: "Vidriería Tres Lomas, long quote", note: "Ten lines" },
  { id: "perfiles-quillen-a30", label: "Perfiles Quillén, A30 line", note: "Prices without decimals" },
  { id: "herrajes-calandria-note", label: "Herrajes Calandria, short note", note: "Informal note in italic type" },
  { id: "aluminios-calden-units", label: "Aluminios Caldén Sur, profiles", note: "Quoted per unit, not per bar" },
];

export function findSample(id: string): SampleQuote | undefined {
  return SAMPLE_QUOTES.find((sample) => sample.id === id);
}

/** Relative to the project root. PDFs live in public/ so the UI can link to them. */
export function samplePdfPath(id: string): string {
  return `public/samples/${id}.pdf`;
}
